import { useState } from "react";
import "./Torneo.css";

function Torneo() {

  const [formData, setFormData] = useState({
    squadra: "",
    referente: "",
    email: "",
    telefono: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log(formData);
    alert("Iscrizione inviata!");
  };

  return (
    <div className="torneo-container">

      <div className="torneo-content">

        <h1 className="torneo-title">Torneo Seriana Cobras</h1>

        <p className="torneo-description">
          Qui potrai inserire la descrizione del torneo,
          le date, il formato delle partite e tutte le
          informazioni utili per le squadre partecipanti.
        </p>

        <form className="torneo-form" onSubmit={handleSubmit}>

          <input
            type="text"
            name="squadra"
            placeholder="Nome squadra"
            onChange={handleChange}
            required
          />

          <input
            type="text"
            name="referente"
            placeholder="Nome referente"
            onChange={handleChange}
            required
          />

          <input
            type="email"
            name="email"
            placeholder="Email"
            onChange={handleChange}
            required
          />

          <input
            type="text"
            name="telefono"
            placeholder="Telefono"
            onChange={handleChange}
          />

          <button type="submit">
            Iscrivi squadra
          </button>

        </form>

      </div>

    </div>
  );
}

export default Torneo;
